<?php
declare(strict_types=1);
require_once __DIR__ . '/api/core/App.php';
$admin = require_role('administrador','superadministrador');
require_permission('empresas.aprobar');
require_permission('oportunidades.aprobar');
require_permission('postulaciones.consultar_todas');
require_permission('bitacora.consultar');
$pdo = db();
// The coordinator sees pending opportunities and controls publication; companies retain ownership of their content.
$pending = $pdo->query("SELECT id_oportunidad,titulo,descripcion,requisitos,ubicacion,modalidad,tipo_practica,remuneracion,moneda,vacantes,fecha_inicio,fecha_fin,fecha_limite_postulacion,COALESCE(NULLIF(estado,''),'pendiente_revision') AS estado,empresa FROM vw_admin_oportunidades WHERE estado='pendiente_revision' OR estado='' OR estado IS NULL ORDER BY id_oportunidad")->fetchAll();
$opportunities = $pdo->query("SELECT id_oportunidad,titulo,COALESCE(NULLIF(estado,''),'pendiente_revision') AS estado,fecha_limite_postulacion,empresa FROM vw_admin_oportunidades WHERE COALESCE(estado,'')<>'borrado' ORDER BY id_oportunidad DESC")->fetchAll();
$pendingCompanies = $pdo->query("SELECT e.id_empresa,e.nombre_legal,e.nombre_comercial,e.identificacion_fiscal,e.sector,e.descripcion,e.correo_contacto,e.telefono,e.sitio_web,e.direccion,e.nombres,e.apellidos,e.correo,e.estado,(SELECT JSON_UNQUOTE(JSON_EXTRACT(b.datos_nuevos,'$.decision')) FROM vw_admin_bitacora b WHERE b.tabla_afectada='empresas' AND b.id_registro=e.id_empresa AND b.accion IN ('REVISION_EMPRESA','REENVIO_EMPRESA') ORDER BY b.id_bitacora DESC LIMIT 1) AS decision_anterior,(SELECT JSON_UNQUOTE(JSON_EXTRACT(b.datos_nuevos,'$.comentario')) FROM vw_admin_bitacora b WHERE b.tabla_afectada='empresas' AND b.id_registro=e.id_empresa AND b.accion='REVISION_EMPRESA' ORDER BY b.id_bitacora DESC LIMIT 1) AS comentario_anterior FROM vw_admin_empresas_revision e WHERE e.estado='pendiente' ORDER BY e.id_empresa DESC")->fetchAll();
$applications = $pdo->query('SELECT id_postulacion,fecha_postulacion,carta_presentacion,observaciones,estado,oportunidad,empresa,nombres,apellidos,correo,telefono,carnet,carrera,semestre,universidad,cv_nombre FROM vw_admin_postulaciones ORDER BY fecha_postulacion DESC')->fetchAll();
$audit = $pdo->query('SELECT id_bitacora,fecha_evento,accion,tabla_afectada,id_registro,datos_anteriores,datos_nuevos,ip_origen,actor FROM vw_admin_bitacora ORDER BY id_bitacora DESC LIMIT 100')->fetchAll();
page_start('Administración');
echo '<section class="page-heading"><div><span class="eyebrow">REVISIÓN DE COORDINACIÓN</span><h1>Administración</h1><p>Aprueba empresas, revisa oportunidades y controla las convocatorias.</p></div><div class="admin-stats"><div><strong>'.count($pending).'</strong><span>oportunidades por revisar</span></div><div><strong>'.count($pendingCompanies).'</strong><span>empresas por aprobar</span></div></div></section>';
echo '<section class="panel company-review" id="empresas"><div class="panel-heading"><div><span class="eyebrow">ACCESO EMPRESARIAL</span><h2>Empresas pendientes</h2></div></div>';
if (!$pendingCompanies) echo '<p class="empty-inline">No hay empresas esperando revisión.</p>';
else foreach ($pendingCompanies as $c) {
    $companyStatusLabels=['solicitar_cambios'=>'Cambios solicitados','rechazar'=>'Rechazada','reenviada'=>'Reenviada','aprobar'=>'Aprobada'];
    echo '<article class="company-review-card"><div class="company-review-summary"><div class="detail-top"><div><strong>'.h($c['nombre_comercial']?:$c['nombre_legal']).'</strong><span>'.h($companyStatusLabels[$c['decision_anterior']]??'Pendiente de revisión').'</span></div><span class="status-pill">Pendiente</span></div>';
    echo '<dl class="company-facts"><dt>Nombre legal</dt><dd>'.h($c['nombre_legal']).'</dd><dt>Nombre comercial</dt><dd>'.h($c['nombre_comercial']?:'No indicado').'</dd><dt>Identificación fiscal</dt><dd>'.h($c['identificacion_fiscal']?:'No indicada').'</dd><dt>Sector</dt><dd>'.h($c['sector']?:'No indicado').'</dd><dt>Descripción</dt><dd>'.nl2br(h($c['descripcion']?:'No proporcionada')).'</dd><dt>Contacto empresarial</dt><dd>'.h($c['correo_contacto']).' · '.h($c['telefono']?:'Sin teléfono').'</dd><dt>Sitio web</dt><dd>'.h($c['sitio_web']?:'No indicado').'</dd><dt>Dirección</dt><dd>'.h($c['direccion']?:'No indicada').'</dd><dt>Usuario responsable</dt><dd>'.h($c['nombres'].' '.$c['apellidos']).' · '.h($c['correo']).'</dd></dl>';
    if(!empty($c['comentario_anterior'])) echo '<div class="student-note"><strong>Comentario de coordinación anterior</strong><p>'.nl2br(h($c['comentario_anterior'])).'</p></div>';
    echo '</div><form class="company-review-decision" method="post" action="'.h(app_url('api/empresas.php')).'" data-review-form>'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_empresa" value="'.h($c['id_empresa']).'"><label for="company-review-'.h($c['id_empresa']).'">Comentario para la empresa <span class="optional">(obligatorio al solicitar cambios o rechazar)</span></label><textarea id="company-review-'.h($c['id_empresa']).'" name="comentario_revision" maxlength="2000" rows="3" data-review-comment placeholder="Indica con claridad qué debe corregir la empresa."></textarea><div class="review-actions"><button class="button button-primary" name="decision" value="aprobar" type="submit">Aprobar empresa</button><button class="button button-quiet" name="decision" value="solicitar_cambios" type="submit">Solicitar cambios</button><button class="text-danger" name="decision" value="rechazar" type="submit">Rechazar</button></div></form></article>';
}
echo '</section><section class="panel" id="oportunidades"><div class="panel-heading"><div><span class="eyebrow">MODERACIÓN</span><h2>Oportunidades enviadas por empresas</h2></div><span class="result-count">'.count($pending).' pendientes</span></div>';
if (!$pending) echo '<p class="empty-inline">No hay oportunidades esperando revisión.</p>';
else foreach ($pending as $o) {
    echo '<article class="company-review-card opportunity-review-card"><div class="opportunity-review-summary"><strong>'.h($o['titulo']).'</strong><span>'.h($o['empresa']).' · '.h($o['modalidad']).' · Cierre '.h($o['fecha_limite_postulacion']).'</span><p>'.h($o['descripcion']).'</p><small>Requisitos: '.h($o['requisitos']?:'No especificados').'</small><a class="button button-quiet" href="'.h(app_url('index.php?id='.$o['id_oportunidad'])).'">Ver oportunidad completa</a></div><form class="opportunity-review-decision" method="post" action="'.h(app_url('api/oportunidades.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_oportunidad" value="'.h($o['id_oportunidad']).'"><label for="revision-comment-'.h($o['id_oportunidad']).'">Comentario para la empresa <span class="optional">(obligatorio al pedir cambios o rechazar)</span></label><textarea id="revision-comment-'.h($o['id_oportunidad']).'" name="comentario_revision" maxlength="2000" rows="3" placeholder="Ejemplo: cambia la remuneración a Q 2,500 y actualiza la fecha de inicio."></textarea><div class="review-actions"><button class="button button-primary" name="decision" value="publicar">Aceptar y publicar</button><button class="button button-quiet" name="decision" value="solicitar_cambios">Solicitar cambios</button><button class="text-danger" name="decision" value="rechazar">Rechazar</button></div></form></article>';
}
echo '</section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">CONVOCATORIAS</span><h2>Oportunidades registradas</h2></div></div><div class="table-wrap"><table><thead><tr><th>Oportunidad</th><th>Estado</th><th>Fecha límite</th><th>Acción</th></tr></thead><tbody>';
foreach ($opportunities as $o) { $stateLabels=['pendiente_revision'=>'En espera de revisión','requiere_cambios'=>'Cambios solicitados','borrador'=>'Borrador','publicada'=>'Publicada','rechazada'=>'Rechazada','pausada'=>'Pausada','cerrada'=>'Cerrada','borrado'=>'Borrada']; echo '<tr><td>'.h($o['titulo']).'<small>'.h($o['empresa']).'</small></td><td><span class="status-pill">'.h($stateLabels[$o['estado']]??'En espera de revisión').'</span></td><td>'.h($o['fecha_limite_postulacion']).'</td><td><a class="button button-small button-quiet" href="'.h(app_url('index.php?id='.$o['id_oportunidad'])).'">Revisar</a>'; if ($o['estado']==='publicada') echo ' <form method="post" action="'.h(app_url('api/oportunidades.php')).'">'.csrf_field().'<input type="hidden" name="_method" value="PUT"><input type="hidden" name="id_oportunidad" value="'.h($o['id_oportunidad']).'"><input type="hidden" name="decision" value="cerrar"><button class="text-danger">Cerrar convocatoria</button></form>'; echo '</td></tr>'; }
echo '</tbody></table></div></section>';
echo '<section class="panel" id="postulaciones"><div class="panel-heading"><div><span class="eyebrow">SEGUIMIENTO GENERAL</span><h2>Postulaciones</h2><p>La empresa responsable acepta o rechaza cada solicitud.</p></div><span class="result-count">'.count($applications).' solicitudes</span></div><div class="table-wrap"><table><thead><tr><th>Estudiante</th><th>Empresa y oportunidad</th><th>Estado</th></tr></thead><tbody>';
foreach($applications as $a) { echo '<tr><td>'.h($a['nombres'].' '.$a['apellidos']).'<small>'.h($a['correo']).'</small><details><summary>Ver perfil y CV</summary><small>'.h($a['telefono']?:'Sin teléfono').' · Carné '.h($a['carnet']).'</small><small>'.h($a['carrera']).' · '.h($a['universidad']).' · '.h($a['semestre']).'</small><small>Carta: '.nl2br(h($a['carta_presentacion']?:'Sin carta de presentación')).'</small><a class="text-link" href="'.h(app_url('api/cv.php?id='.$a['id_postulacion'])).'">Descargar '.h($a['cv_nombre']?:'CV').'</a></details></td><td>'.h($a['empresa']).'<small>'.h($a['oportunidad']).'</small></td><td><span class="status-pill">'.h($a['estado']).'</span>'.(!empty($a['observaciones'])?'<small>'.($a['estado']==='rechazada'?'Motivo del rechazo: ':'Nota de seguimiento: ').h($a['observaciones']).'</small>':'').'</td></tr>'; }
echo '</tbody></table></div></section>';
echo '<section class="panel" id="bitacora"><div class="panel-heading"><div><span class="eyebrow">TRAZABILIDAD</span><h2>Bitácora reciente</h2><p>Últimos 100 cambios guardados con instantánea JSON e IP de origen.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha y actor</th><th>Acción</th><th>Registro</th><th>Antes → después</th><th>IP</th></tr></thead><tbody>';
foreach($audit as $event) echo '<tr><td>'.h($event['fecha_evento']).'<small>'.h($event['actor']?:'Sistema').'</small></td><td>'.h($event['accion']).'</td><td>'.h($event['tabla_afectada']).' #'.h($event['id_registro']).'</td><td><small>'.h($event['datos_anteriores']?:'—').'</small><small>'.h($event['datos_nuevos']?:'—').'</small></td><td>'.h($event['ip_origen']?:'—').'</td></tr>';
echo '</tbody></table></div></section>';
page_end();

